  auto _ANTENNAS = _o->ANTENNAS.size() ? _fbb.CreateVectorOfStrings(_o->ANTENNAS) : 0;
  auto _BATTERIES = _o->BATTERIES.size() ? _fbb.CreateVectorOfStrings(_o->BATTERIES) : 0;
  auto _SOLAR_ARRAYS = _o->SOLAR_ARRAYS.size() ? _fbb.CreateVectorOfStrings(_o->SOLAR_ARRAYS) : 0;
  auto _THRUSTERS = _o->THRUSTERS.size() ? _fbb.CreateVectorOfStrings(_o->THRUSTERS) : 0;
